%[text] # Demo 5: Acceleration-dependent Feedforward Experiment
%[text] **目的:** 位置・速度・加速度から必要な電流指令を計算するFFマップを作り、別の軌道でも追従誤差が減るかを確認する。
%[text] **手順:** 6種類の往復軌道でILCを収束させる → 学習済みFFから位置ごとの4係数を同定 → 未学習の2軌道でFBとマップFFを比較する。
%[text] **実機が動く節:** 4と6。全体実行すると、Homing・計測・保存まで自動で進む。Targetの選択操作は不要。
%[text] ## 1. Load settings and design the feedback controller
clear; close all;
% Live Editor may execute a temporary copy; resolve the root from the function.
projectRoot = setup_project();
run(fullfile(projectRoot, "config", "config_tunable.m"));

load(fullfile(projectRoot, "config", "data", "pana_params.mat"));
[plant, plantPath] = load_experiment_plant( ...
    projectRoot, plantDataFile, Ts);
Pd = plant.Pd;
Jn = plant.Jn;
Dn = plant.Dn;
Ndelay = plant.Ndelay;
fprintf("Sample rate: %.0f Hz, plant: %s\n", 1/Ts, plantPath); %[output:181c56c4]

Pd0 = struct( ...
    "m", Jn, ...
    "d", Dn, ...
    "k", 0, ...
    "delay", Ndelay, ...
    "lp", [0, 0, 0]);
[~, Gn0] = modelCreate(Pd0, Ts, Pd.Frequency);
Pdn = Gn0.modelDelayed;

[fb, ~, ~] = fbDesign(Pd, Ts);
Kd = fb.K;
feedbackFlag = 1;
%%
%[text] ## Check stability and sensitivity before operating the stage
%[text] exp04と同じFBを使う。名目閉ループが不安定、または実測感度のピークが2以上なら、実機取得へ進まずに停止する。
Smax = 2;
S = feedback(1, Pd*Kd);
sensitivityPeak = max(abs(squeeze(freqresp(S))));
assert(isstable(feedback(Pdn*Kd, 1)), "NikonMotor:UnstableFeedback", ...
    "The nominal closed loop must be stable before operating the stage.");
assert(isfinite(sensitivityPeak) && sensitivityPeak < Smax, ...
    "NikonMotor:SensitivityLimit", ...
    "Measured sensitivity must be below the operating limit.");
fprintf("Preflight: nominal stable, sensitivity %.6f < %.1f\n", ... %[output:group:6b7b22fc] %[output:31f1c150]
    sensitivityPeak, Smax); %[output:group:6b7b22fc] %[output:31f1c150]

figure; %[output:3cbb16df]
bode(Pdn, Pd, bop); %[output:3cbb16df]
legend("Model", "Measured", "Location", "northwest"); %[output:3cbb16df]
grid on; %[output:3cbb16df]

theta = linspace(0, 2*pi, 1000);
figure; %[output:703c97c1]
nyquistplot(Pdn*Kd, nop); hold on; %[output:703c97c1]
nyquistplot(Pd*Kd, nop); %[output:703c97c1]
plot(cos(theta)/Smax-1, sin(theta)/Smax, "k--"); hold off; %[output:703c97c1]
legend("Nominal", "Measured", "1/Smax boundary"); %[output:703c97c1]

SmaxFrd = frd(Smax*ones(numel(Pd.Frequency), 1), ...
    Pd.Frequency, "FrequencyUnit", "Hz");
figure; %[output:571a1c42]
bodemag(S, bop); hold on; %[output:571a1c42]
bodemag(SmaxFrd, bop, "k--"); hold off; %[output:571a1c42]
legend("Measured sensitivity", "Smax"); %[output:571a1c42]
%%
%[text] ## 2. Generate the training and comparison trajectories
%[text] 同じ位置を異なる速度・加速度で通過するデータが必要なので、最大速度と加速位置を変えた6軌道を使う。可動距離1.25 m・最大速度2.0 m/sはexp04のneo実験を基準にする。
%[text] v\_max\_listで同定用の最大速度を指定し、片道時間duration\_listは軌道形状から自動計算する。warpは加速位置を変える無次元のパラメーター。各軌道で最大Ntrial回のILCを行い、収束した最終FFを1本の教師とする。
dist = 1.25;                  % Travel distance [m]
startCount = 54100000;         % Absolute start position [encoder count]
endCountLimit = 66655810;      % Upper travel limit [encoder count]
t_pre = 1.5;                   % Idle time before motion [s]
t_pause = 1.0;                 % Dwell at the turn-around point [s]
t_post = 1.5;                  % Idle time after motion [s]

v_max_list = [1.0, 1.0, 1.5, 1.5, 2.0, 2.0]; % Training peak velocities [m/s]
warp_list = [-0.65, 0.65, -0.65, 0.65, -0.65, 0.65];
Ntrial = 80;                  % Total trials, including relearning and resumed validation
reuseSavedTeachers = true;    % Revalidate accepted ILC data before reusing it
teacherDataFile = fullfile(projectRoot,"data","acceleration_ff","current_teachers.mat");
% Per-profile prediction allowance from prior captures; physical limit stays 2 A.
predictionMarginList = [.04, .15, .07, .07, .15, .15];
% Prior 420 Hz ILC: [whole RMS, moving RMS, peak] [um].
teacherAccuracyLimits = 1e-6*[ ...
    5.5710, 3.9098, 29.5; ...
    8.0833, 8.8558, 49.4; ...
    7.6734, 7.5661, 61.2; ...
    5.8409, 5.6962, 34.1; ...
    13.2434,18.3450,105.3; ...
    11.3011,14.0634,112.0];
test_v_max_list = [1.25, 1.75]; % Untrained comparison velocities [m/s]
test_warp_list = [-0.25, 0.25];

trackingLimit = 3e-3;          % Maximum tracking error [m]
terminalLimit = 100e-6;        % Return-to-start tolerance [m]
derivativeWindow = 81;         % Local cubic differentiation window [samples]
currentOffsetSamples = -Ndelay;
% Row 7 logs the same delayed FF that enters the control sum. Do not undo
% Reference/Delay1 again; retain the nominal command-to-motion alignment.
xGrid = startCount*ENCODER_RESOLUTION + (0.0005:0.0005:dist-0.0005)';
blendDistance = 0.0005;        % Join to the measured map's endpoint coefficients [m]
mapGain = 1;                   % 0: ordinary FF, 1: identified total FF

% Preserve the exp04 learning bandwidth; saturation is handled in the update.
Fc = 420;
[Qz, Qp, Qgain] = butter(4, Fc/(1/(2*Ts)));
[Qsos, Qscale] = zp2sos(Qz, Qp, Qgain);
teacherOptions = struct('minTrials',5, 'window',3, ...
    'averagingWindow',8, 'validationTrials',8, ...
    'errorRelativeChange',0.05, 'ffRelativeChange',0.05, 'feedbackRatio',0.20, ...
    'trackingLimit',trackingLimit, 'terminalLimit',terminalLimit, ...
    'maxInput',MAX_INPUT, 'endPosition',endCountLimit*ENCODER_RESOLUTION);
assert(isequal(size(teacherAccuracyLimits),[numel(v_max_list),3]) && ...
    all(isfinite(teacherAccuracyLimits) & teacherAccuracyLimits>0,'all') && ...
    numel(predictionMarginList)==numel(v_max_list) && ...
    all(isfinite(predictionMarginList) & predictionMarginList>0 & predictionMarginList<MAX_INPUT), ...
    'NikonMotor:TeacherSettings','Provide accuracy limits and prediction margins for every profile.');

endCount = startCount + dist/ENCODER_RESOLUTION;
assert(endCount + (trackingLimit + terminalLimit)/ENCODER_RESOLUTION < endCountLimit, ...
    "NikonMotor:TrajectoryRange", ...
    "Leave room for Homing tolerance and tracking error before the travel limit.");
fprintf("Travel: %.0f to %.0f count, upper margin %.3f mm\n", ... %[output:group:3b1f4f4e] %[output:8ac8f150]
    startCount, endCount, (endCountLimit-endCount)*ENCODER_RESOLUTION*1e3); %[output:group:3b1f4f4e] %[output:8ac8f150]

% Ordinary FF coefficients use the same order as exp03.
Kfj = 0;
Kfa = 0;
Kfv = 0;
Kfc = 0;
ffGains = [Kfj; Kfa; Kfv; Kfc];

allSpeeds = [v_max_list, test_v_max_list];
allWarps = [warp_list, test_warp_list];
allDurations = zeros(size(allSpeeds));
allProfiles = cell(size(allSpeeds));
for k = 1:numel(allProfiles)
    % Velocity scales inversely with duration. One extra sample keeps the
    % resampled profile below its requested peak velocity after rounding.
    unitProfile = generate_acceleration_profile(dist, 1, allWarps(k), Ts, [0, 0, 0]);
    allDurations(k) = ceil(max(abs(unitProfile.vel))/allSpeeds(k)/Ts)*Ts + Ts;
    allProfiles{k} = generate_acceleration_profile( ...
        dist, allDurations(k), allWarps(k), Ts, [t_pre, t_pause, t_post]);
    assert(max(abs(allProfiles{k}.vel)) <= allSpeeds(k), ...
        "NikonMotor:TrajectorySpeed", "Generated trajectory exceeds its velocity limit.");
end
profiles = allProfiles(1:numel(v_max_list));
testProfiles = allProfiles(numel(v_max_list)+1:end);
duration_list = allDurations(1:numel(v_max_list));
test_duration_list = allDurations(numel(v_max_list)+1:end);

figure; %[output:36347800]
tiledlayout(3, 1); %[output:36347800]
for k = 1:numel(allProfiles) %[output:group:7d16dfdf]
    traj = allProfiles{k};
    prepare_tunable_trajectory_parameters( ...
        traj.pos, zeros(size(traj.pos)), tunable_trajectory_buffer_capacity());

    nexttile(1); plot(traj.time, traj.pos); hold on; %[output:36347800]
    ylabel("Position [m]"); grid on;
    nexttile(2); plot(traj.time, traj.vel); hold on;
    ylabel("Velocity [m/s]"); grid on;
    nexttile(3); plot(traj.time, traj.acc); hold on;
    ylabel("Acceleration [m/s^2]"); grid on;

    fprintf("Profile %d: %.3f m/s, %.3f m/s^2, %d samples\n", ... %[output:39c6e24d]
        k, max(abs(traj.vel)), max(abs(traj.acc)), numel(traj.pos)); %[output:39c6e24d]
end %[output:group:7d16dfdf]
xlabel("Time [s]"); %[output:36347800]
%%
%[text] ## 3. Build the tunable model only when required
%[text] モデル・制御器・周期を変更した場合だけビルド・配備が必要。軌道やFF係数だけの変更ではfalseのまま実行する。
rebuildTarget = false;
if rebuildTarget
    run(fullfile(projectRoot, "exp03_FF", "setup_tunable.m"));
end
%%
%[text] ## 4. Collect the converged ILC teachers
%[text] **実機動作:** 各軌道の前にHomingし、FF=0からexp04と同じILCを最大Ntrial反復する。開始位置のずれが100 µmを超えたときだけ自動Homing・再接続し、学習済みFFを引き継ぐ。Target選択や確認ダイアログは不要。
%[text] 最低16試行を学習し、8本平均FFの直近3更新の変化が5%以内、直近8試行が無飽和なら、その平均FFを最低8回固定して実測する。誤差RMSの変化5%以内・残留FB/FF比20%以内に加え、全区間RMS・移動中RMS・最大誤差が従来420 Hzの基準以下である最終適用FFを教師に採用する。
%[text] 途中の総電流飽和は記録してILCを続ける。最終試行が飽和している場合は教師に採用しない。未収束・欠落・追従不良・停止確認の失敗は保存して停止する。teacher\_progress.matには反復履歴、training\_progress.matには採用済み教師の一覧を残す。
%[text] 採用済み6教師の一覧current\_teachers.matがある場合は再利用する。節5で軌道・制御設定・精度を再判定する。最初から取り直す場合はreuseSavedTeachers=falseにする。
method = "ilc_teacher";
if reuseSavedTeachers && isfile(teacherDataFile)
    savedTeachers = load(teacherDataFile,"trainingFiles");
    trainingFiles = savedTeachers.trainingFiles;
    assert(numel(trainingFiles)==numel(profiles) && all(isfile(trainingFiles)), ...
        'NikonMotor:MissingTeacherData','The accepted teacher list must contain all six source files.');
    fprintf('Reusing %d ILC teachers; their settings and accuracy are checked before fitting.\n',numel(trainingFiles));
else
    experimentRunDir = create_run_directory("data/acceleration_ff", "training");
    trainingFiles = strings(0, 1);
    for profileIndex = 1:numel(profiles) %[output:group:7fcc3f50]
        traj = profiles{profileIndex};
        r = traj.pos;
        f = zeros(size(r));

        runTag = sprintf("profile_%02d_ilc_teacher", profileIndex);
        [~, homing] = home_to_start(startCount); %[output:04e03b99]
        run(fullfile(projectRoot, "exp05_AccelerationFF", "obtainMeasurement.m")); %[output:353fd24f] %[output:13e88d4a] %[output:6dde871d] %[output:7d80bd7d] %[output:3afc9bcb]

        trainingFiles(end+1, 1) = string(resultFile); %#ok<SAGROW>
        save_experiment_result(experimentRunDir, "training_progress", ...
            struct("trainingFiles", trainingFiles, ...
            "duration_list", duration_list, "warp_list", warp_list, ...
            "v_max_list", v_max_list, "Ntrial", Ntrial, "teacherOptions", teacherOptions, ...
            "teacherAccuracyLimits",teacherAccuracyLimits,"predictionMarginList",predictionMarginList, ...
            "Fc", Fc, "Qsos", Qsos, "Qscale", Qscale, ...
            "dist", dist, "startCount", startCount, "xGrid", xGrid, ...
            "derivativeWindow", derivativeWindow, ...
            "currentOffsetSamples", currentOffsetSamples));
    end %[output:group:7fcc3f50]
end
%%
%[text] ## 5. Identify and inspect the position-dependent coefficients
%[text] **実機動作なし:** 収束したILCのFF（ログ7行目）を、i = g(x) + b(x)v + c(x)sign(v) + alpha(x)a に当てはめる。総電流指令（3行目）は残留FBの診断に使う。速度vと加速度aは実測位置を微分して求める。
%[text] 求めるのは、位置だけに依存する項g、速度に比例する係数b、移動方向に依存する係数c、加速度に比例する係数alphaの4マップ。係数図の欠落は同定できなかった位置を表す。
%[text] 各教師の最後の固定8回を位置ごとに平均して同定する。同じ軌道の反復を別の教師形状には数えない。再生時は方向別の実測FF範囲を使い、係数の組合せによる突出を抑える。
%[text] 収録済みのtraining\_progress.matをloadしてからこの節を実行すれば、実機の再計測なしで再同定できる。
training = cell(numel(trainingFiles)*teacherOptions.validationTrials,1);
for k = 1:numel(trainingFiles)
    data = load(trainingFiles(k));
    assert(data.profileIndex==k && data.Fc==Fc && data.Ts==Ts && data.Ndelay==Ndelay && ...
        isequal(data.Kd,Kd) && isequal(data.Qsos,Qsos) && isequal(data.Qscale,Qscale) && ...
        strcmp(data.plantPath,plantPath) && isequal(data.traj.pos,profiles{k}.pos) && ...
        isequal(data.traj.vel,profiles{k}.vel), 'NikonMotor:TrainingSettingsMismatch', ...
        'Saved teacher settings differ. Set reuseSavedTeachers=false to collect the configured trajectories.');
    limits = teacherAccuracyLimits(data.profileIndex,:);
    settings = data.teacher.settings;
    settings.rmsLimit = limits(1); settings.movingRmsLimit = limits(2);
    settings.peakErrorLimit = limits(3);
    checked = evaluate_ilc_teacher(data.history,data.completedTrials,data.traj.vel,settings);
    assert(checked.converged && checked.accuracyPassed,'NikonMotor:TrainingAccuracyFailed', ...
        'Saved profile %d does not meet the configured accuracy limits.',data.profileIndex);
    ix = data.completedTrials-teacherOptions.validationTrials+1:data.completedTrials;
    for j = 1:numel(ix)
        training{(k-1)*numel(ix)+j} = struct('passed',data.passed,'method',data.method, ...
            'profileIndex',k,'teacher',checked,'Ts',Ts, ...
            'y_absolute_ex',data.history.y_absolute(:,ix(j)), ...
            'ff_ex',data.history.ff(:,ix(j)),'count_ex',data.history.count(:,ix(j)), ...
            'r_ex',data.history.r(:,ix(j)));
    end
    clear data
end
ffMap = fit_acceleration_ff( ...
    training, xGrid, derivativeWindow, currentOffsetSamples);
assert(all(ffMap.valid),'NikonMotor:InvalidAccelerationMap','Every operating map position must be identified.');
save(teacherDataFile,'trainingFiles');

figure;
tiledlayout(4, 1);
units = ["g [A]", "b [A s/m]", "c [A]", "alpha [A s^2/m]"];
for k = 1:4
    nexttile;
    plot(ffMap.x, ffMap.coefficients(:, k));
    grid on;
    ylabel(units(k));
end
xlabel("Absolute position [m]");
fprintf("Identified %d/%d positions; invalid coefficients remain NaN.\n", ...
    nnz(ffMap.valid), numel(ffMap.valid));

mapRunDir = create_run_directory("data/acceleration_ff", "map");
mapFile = save_experiment_result(mapRunDir, "acceleration_map", ...
    struct("ffMap", ffMap, "trainingFiles", trainingFiles, "Ts", Ts, ...
    "Kd", Kd, "plantPath", plantPath, "Ndelay", Ndelay));
save_experiment_figures(mapRunDir, gcf);
%%
%[text] ## 6. Compare feedforward on the untrained trajectories
%[text] **実機動作:** 同定に使わなかった2軌道で、同じFBに対してFFを切り替える。ここではマップを再学習せず、RMS誤差・加減速中RMS・最大誤差・最大電流を比較する。
%[text] fbはFFなし、ordinaryはexp03と同じ係数式、accelerationは今回同定したマップ。通常FF係数がすべて0なら、fbと重複するordinaryの試行を省く。
methods = ["fb", "ordinary", "acceleration"];
if all(ffGains == 0)
    methods = ["fb", "acceleration"];
    fprintf("Ordinary FF is zero; its duplicate FB run is skipped.\n");
end

experimentRunDir = create_run_directory("data/acceleration_ff", "comparison");
save_experiment_result(experimentRunDir, "comparison_settings", ...
    struct("ffMap", ffMap, "mapFile", mapFile, "ffGains", ffGains, ...
    "mapGain", mapGain, "blendDistance", blendDistance, "Ts", Ts, "Kd", Kd, ...
    "testProfiles", {testProfiles}, "test_v_max_list", test_v_max_list, ...
    "methods", methods, "Ndelay", Ndelay));
comparison = table();

for profileIndex = 1:numel(testProfiles)
    traj = testProfiles{profileIndex};
    r = traj.pos;
    baseline = [traj.jerk, traj.acc, traj.vel, sign(traj.vel)]*ffGains;

    comparisonFigure = figure;
    tiledlayout(3, 1);
    for method = methods
        [~, homing] = home_to_start(startCount);
        f = baseline;
        if method == "fb"
            f = zeros(size(r));
        elseif method == "acceleration"
            origin = homing.final_count*ENCODER_RESOLUTION;
            edge = ffMap.coefficients([1,end],:);
            ix = 1+double(origin+traj.pos>mean(ffMap.x([1,end])));
            edgeBaseline = sum(edge(ix,:).* ...
                [ones(size(r)),traj.vel,sign(traj.vel),traj.acc],2);
            w = min(max((abs(traj.vel)-.002)/.002,0),1);
            edgeBaseline = edgeBaseline.*w.^2.*(3-2*w);
            mapped = acceleration_feedforward(ffMap,traj,origin,edgeBaseline,1,blendDistance);
            f = baseline+mapGain*(mapped-baseline);
        end

        % Advance the combined FF once, matching exp03's delay compensation.
        f = [f(1+Ndelay:end); repmat(f(end), Ndelay, 1)];
        runTag = sprintf("profile_%02d_%s", profileIndex, method);
        run(fullfile(projectRoot, "exp05_AccelerationFF", "obtainMeasurement.m"));

        accelerating = abs([0; traj.acc(1:end-1)]) > 0.02;
        moving = abs([0; traj.vel(1:end-1)]) > 0.002;
        rmsMoving = sqrt(mean(e_ex(moving).^2));
        rmsAccelerating = sqrt(mean(e_ex(accelerating).^2));
        comparison = [comparison; table( ...
            profileIndex, method, trialResult.rmsError, rmsMoving, rmsAccelerating, ...
            trialResult.peakError, max(abs(u_ex)), string(resultFile), ...
            'VariableNames', ["profile", "method", "rmsError", ...
            "rmsMoving", "rmsAccelerating", "peakError", "peakCurrent", "resultFile"])]; %#ok<AGROW>
        save_experiment_result(experimentRunDir, "comparison", ...
            struct("comparison", comparison));

        figure(comparisonFigure);
        nexttile(1); plot(t_ex, e_ex, "DisplayName", method); hold on;
        ylabel("Error [m]"); grid on; legend;
        nexttile(2); plot(t_ex, ff_ex, "DisplayName", method); hold on;
        ylabel("FF [A]"); grid on;
        nexttile(3); plot(t_ex, u_ex, "DisplayName", method); hold on;
        ylabel("Total input [A]"); xlabel("Time [s]"); grid on;
        save_experiment_figures(runDir, comparisonFigure);
    end
    referenceRow = comparison(comparison.profile==profileIndex & comparison.method=="fb",:);
    mapRow = comparison(comparison.profile==profileIndex & comparison.method=="acceleration",:);
    assert(all(mapRow{1,3:6}<referenceRow{1,3:6}), 'NikonMotor:MapAccuracyFailed', ...
        'Map FF must improve whole, moving, acceleration and peak error over the matching FB trial.');
end
%%
%[text] ## Inspect the comparison result
%[text] 誤差の単位はm、電流の単位はA。完了表示は教師の精度、全位置の同定、未学習軌道でのFB比の誤差改善、非飽和、停止確認を通過したことを表す。教師の精度と未学習軌道の精度は別々に比較表で確認する。
disp(comparison);
fprintf("ACCELERATION_FF_COMPLETE: %d training runs, %d comparisons, map %d/%d valid.\n", ...
    numel(trainingFiles), height(comparison), nnz(ffMap.valid), numel(ffMap.valid));
fprintf("Map: %s\nComparison: %s\n", mapFile, experimentRunDir);

%[appendix]{"version":"1.0"}
%---
%[metadata:view]
%   data: {"layout":"inline"}
%---
%[output:181c56c4]
%   data: {"dataType":"text","outputData":{"text":"Sample rate: 4000 Hz, plant: C:\\Users\\AKZW\\Documents\\MATLAB\\NikonMotorProject2025\\data\\plants\\4khz\\current.mat\n","truncated":false}}
%---
%[output:31f1c150]
%   data: {"dataType":"text","outputData":{"text":"Preflight: nominal stable, sensitivity 1.511372 < 2.0\n","truncated":false}}
